package com.via.model.economy;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

/**
 * Defines the output products generated by a production cycle in a {@link Facility}.
 * <p>
 * A ProductionRule specifies all the goods (and their quantities) that are
 * produced when the inputs defined in the corresponding {@link ConsumptionRule}
 * are consumed.
 */
public class ProductionRule implements Serializable {
    private static final long serialVersionUID = 1L;

    /** List of goods and quantities produced per production cycle */
    private final List<ProductionItem> outputs;

    /**
     * Constructs a new ProductionRule.
     *
     * @param outputs list of {@link ProductionItem} defining what is produced
     */
    public ProductionRule(List<ProductionItem> outputs) {
        this.outputs = new ArrayList<>(outputs);
    }

    /**
     * Returns the list of output items produced by this rule.
     *
     * @return an unmodifiable view of the produced items (defensive copy was made at construction)
     */
    public List<ProductionItem> getOutputs() {
        return outputs;
    }
}
